{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "A large polyphenolic glycoside showed very low mouse brain uptake (0.003% of injected dose) and was characterized as a poor brain penetrant, supporting poor CNS access for the similarly large, polar, glycosylated query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "The cardiac glycoside SC-4453 had the lowest brain concentration among tissues at steady state in guinea pigs, demonstrating effective blood-brain barrier exclusion of a large glycosylated natural product.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Mithramycin, an anthracycline-related polyhydroxy glycoside, showed a peak CSF:plasma ratio of only 0.12 in monkeys with little material found in normal brains, directly supporting poor CNS penetration for the query's anthracycline-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Digitoxin exhibited a very low CSF/plasma ratio (0.01-0.03) in dogs, indicating that large glycosylated natural products do not easily cross the blood-brain barrier.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Erythromycin, a large glycosylated macrolide with transporter liability, achieved CSF concentrations far below serum concentrations in humans, supporting inadequate CNS access for large polar glycosides with efflux susceptibility.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is an anthracycline glycoside (daunorubicin-like) with high molecular weight, high polarity, extensive ionization, and known P-glycoprotein substrate features. All transferable experimental evidence from large polar glycosides and anthracycline-related compounds points to poor brain penetration and inadequate CNS access. The physicochemical prior and consistent experimental analogues support a fail prediction.",
  "evidence_gaps": [
    "No direct brain or CSF pharmacokinetic measurement for the exact query molecule was provided.",
    "Exact human CNS exposure data for daunorubicin itself are not included in the supplied evidence set.",
    "Quantitative contribution of specific efflux transporters (P-gp/BCRP) to the query's brain disposition was not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

